'use strict';

// The user guide (docs/user-guide/README.md) images: every referenced image exists, and
// every image under img/ is referenced (a renamed scene in tools/user-guide/
// user-guide-shots.js must not leave a broken image / orphan file). The images are
// regenerated by `npm run user-guide-shots`.

const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');

const root = path.join(__dirname, '..', '..');
const guideDir = path.join(root, 'docs', 'user-guide');
const guide = fs.readFileSync(path.join(guideDir, 'README.md'), 'utf8');
const refs = [...new Set([...guide.matchAll(/\]\((img\/[^)\s]+)\)/g)].map((m) => m[1]))];

test('the images referenced in the guide exist', () => {
    assert.ok(refs.length >= 10, `only ${refs.length} image references`);
    const missing = refs.filter((rel) => !fs.existsSync(path.join(guideDir, rel)));
    assert.deepEqual(missing, [], `missing image(s): ${missing.join(', ')}`);
});

test('every docs/user-guide/img/ image is referenced in the guide', () => {
    const files = fs.readdirSync(path.join(guideDir, 'img')).map((f) => `img/${f}`);
    const orphans = files.filter((f) => !refs.includes(f));
    assert.deepEqual(orphans, [], `orphan image(s): ${orphans.join(', ')}`);
});

test('every scene of the screenshot tool is an image in the guide', () => {
    const src = fs.readFileSync(path.join(root, 'tools', 'user-guide', 'user-guide-shots.js'), 'utf8');
    const scenes = [...src.matchAll(/\['(\d\d-[a-z0-9-]+)',/g)].map((m) => `img/${m[1]}.jpg`);
    assert.ok(scenes.length >= 10, `only ${scenes.length} scenes`);
    const unused = scenes.filter((f) => !refs.includes(f));
    assert.deepEqual(unused, [], `scene(s) not in the guide: ${unused.join(', ')}`);
});
